// Ask the Mac which YouTube readings are due (24h and 7d after publishing). The Mac decides; n8n only relays.
const due = await this.helpers.httpRequest({ url: 'http://host.docker.internal:5680/metrics-due', json: true });
return due.map((d) => ({ json: d }));

// One metrics row per reading. YouTube's basic statistics have views only; reach = views (Shorts) until the Analytics API is wired.
const due = $('Readings due').all();
const rows = $input.all().flatMap((item, i) => {
  if (!item.json.statistics) return []; // video gone or not readable: skip, it stays due
  const d = due[i].json;
  const views = Number(item.json.statistics?.viewCount ?? 0);
  return [{ storyboard_id: d.storyboard_id, channel: d.channel, platform: 'youtube', window: d.window, reach: views, views }];
});
if (!rows.length) return [{ json: { recorded: 0 } }];
const r = await this.helpers.httpRequest({ method: 'POST', url: 'http://host.docker.internal:5680/metrics', body: rows, json: true });
return [{ json: r }];
